function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function inlineText(node){if(node.type==='text'){let value=esc(node.text);for(const mark of node.marks||[]){if(mark.type==='bold')value=`<strong>${value}</strong>`;else if(mark.type==='italic')value=`<em>${value}</em>`;else if(mark.type==='underline')value=`<u>${value}</u>`;else if(mark.type==='strike')value=`<s>${value}</s>`;else if(mark.type==='superscript')value=`<sup>${value}</sup>`;else if(mark.type==='subscript')value=`<sub>${value}</sub>`;else if(mark.type==='textStyle'){const a=mark.attrs||{};const styles=[];if(typeof a.fontFamily==='string')styles.push(`font-family:"${esc(a.fontFamily.replace(/["<>]/g,''))}"`);if(Number.isFinite(a.fontSize)&&a.fontSize>0)styles.push(`font-size:${Math.min(200,Math.max(1,a.fontSize))}pt`);if(typeof a.color==='string'&&/^#[0-9a-f]{6}$/i.test(a.color))styles.push(`color:${a.color}`);if(styles.length)value=`<span style="${styles.join(';')}">${value}</span>`;}else if(mark.type==='highlight'){const color=mark.attrs?.color;if(typeof color==='string'&&/^#[0-9a-f]{6}$/i.test(color))value=`<mark style="background-color:${color}">${value}</mark>`;}}return value;}if(node.type==='placeholder'){const key=node.attrs?.key||'unknown';return `<span class="placeholder" data-inline-atom="true">{{${esc(key)}}}</span>`}if(node.type==='hardBreak')return '<br>';if(node.type==='pageNumber')return '<span class="placeholder">{{pageNumber}}</span>';return '';}
function paragraphStyle(node){const a=node.attrs||{};const px=v=>`${Number(v)/15}px`;const styles=[`text-align:${esc(a.align||'left')}`];for(const [key,css] of [['spacingBefore','margin-top'],['spacingAfter','margin-bottom'],['indentLeft','margin-left'],['indentRight','margin-right'],['firstLineIndent','text-indent']])if(Number.isFinite(a[key]))styles.push(`${css}:${px(a[key])}`);if(Number.isFinite(a.lineSpacing)&&a.lineSpacing>0){if(a.lineSpacingRule==='auto')styles.push(`line-height:${Number(a.lineSpacing)/240}`);else styles.push(`line-height:${px(a.lineSpacing)}`)}return styles.join(';')}
function blockHtml(node){if(node.type==='table'){const ta=node.attrs||{};const tableStyle=[];if(Number.isFinite(ta.width)&&ta.width>0)tableStyle.push(`width:${ta.width/15}px`);if(ta.layout==='fixed')tableStyle.push('table-layout:fixed');return `<table style="${tableStyle.join(';')}">${(node.content||[]).map(row=>{const ra=row.attrs||{};return `<tr style="${Number.isFinite(ra.height)&&ra.height>0?`height:${ra.height/15}px`:''}">${(row.content||[]).map(cell=>{const a=cell.attrs||{};const styles=[];if(Number.isFinite(a.width)&&a.width>0)styles.push(`width:${a.width/15}px`);if(a.backgroundColor)styles.push(`background-color:${a.backgroundColor}`);if(a.verticalAlign)styles.push(`vertical-align:${a.verticalAlign}`);for(const side of ['Top','Right','Bottom','Left'])if(typeof a['border'+side]==='string')styles.push(`border-${side.toLowerCase()}:${a['border'+side]}`);return `<td colspan="${a.colspan||1}" rowspan="${a.rowspan||1}" style="${styles.join(';')}">${(cell.content||[]).map(blockHtml).join('')}</td>`}).join('')}</tr>`}).join('')}</table>`}const txt=(node.content||[]).map(x=>x.id?blockHtml(x):inlineText(x)).join('');if(node.type==='heading')return `<h2 data-block-id="${esc(node.id||'')}" style="${paragraphStyle(node)}">${txt}</h2>`;if(node.type==='image'){const src=typeof node.attrs?.src==='string'&&/^data:image\/(png|jpeg|gif|bmp);base64,/i.test(node.attrs.src)?node.attrs.src:null;const width=Number.isFinite(node.attrs?.width)&&node.attrs.width>0?`width:${Math.min(2000,node.attrs.width)}px;`:'';const height=Number.isFinite(node.attrs?.height)&&node.attrs.height>0?`height:${Math.min(2000,node.attrs.height)}px;`:'';const posX=node.attrs?.positionX,posY=node.attrs?.positionY;const freePos=Number.isFinite(posX)&&Number.isFinite(posY)&&posX>=0&&posY>=0;if(src&&freePos)return `<div class="document-image free-positioned-image" data-free-image="1" style="left:${posX}px;top:${posY}px"><img draggable="false" src="${src}" alt="${esc(node.attrs?.alt||'Imported image')}" style="${width}${height}max-width:none;object-fit:contain" /></div>`;return src?`<div class="document-image" style="justify-content:${node.attrs?.align==='left'?'flex-start':node.attrs?.align==='right'?'flex-end':'center'}"><img draggable="false" src="${src}" alt="${esc(node.attrs?.alt||'Imported image')}" style="${width}${height}max-width:100%;object-fit:contain" /></div>`:`<div class="image-placeholder">Image: ${esc(node.attrs?.alt||'embedded image unavailable')}</div>`;}if(node.type==='pageBreak')return '<hr>';if(node.type==='horizontalRule')return '<hr>';if(['paragraph','codeBlock'].includes(node.type))return `<p data-block-id="${esc(node.id||'')}" style="${paragraphStyle(node)}">${txt.replace(/\n/g,'<br>')||'<br>'}</p>`;return `<div>${txt}</div>`;}
// Page dimensions are stored in twips (1/1440 inch), matching the DOCX page model.
const PAGE_SIZES={
  A0:{width:47679,height:67408},A1:{width:33703,height:47679},A2:{width:23811,height:33703},A3:{width:16838,height:23811},A4:{width:11906,height:16838},A5:{width:8391,height:11906},A6:{width:5953,height:8391},
  B4:{width:14173,height:20013},B5:{width:9978,height:14173},B6:{width:7087,height:9978},
  Letter:{width:12240,height:15840},Legal:{width:12240,height:20160},Tabloid:{width:15840,height:24480},Ledger:{width:24480,height:15840},Executive:{width:10440,height:15120},Statement:{width:7920,height:12240},Folio:{width:12240,height:18720}
};
const PAGE_MARGINS={normal:{top:1440,right:1440,bottom:1440,left:1440,header:720,footer:720},narrow:{top:720,right:720,bottom:720,left:720,header:360,footer:360},wide:{top:1440,right:2160,bottom:1440,left:2160,header:720,footer:720}};
function applyPagePreview(doc,paper){const page=doc.sections[0]?.page;if(!page)return;const size=page.size||PAGE_SIZES.A4;const landscape=page.orientation==='landscape';const width=(landscape?size.height:size.width)/1440*96;const height=(landscape?size.width:size.height)/1440*96;paper.style.width=`${width}px`;paper.style.maxWidth='none';paper.style.minHeight=`${height}px`;paper.style.padding=`${(page.margins.top/1440*96)}px ${(page.margins.right/1440*96)}px ${(page.margins.bottom/1440*96)}px ${(page.margins.left/1440*96)}px`;const sizeName=Object.keys(PAGE_SIZES).find(k=>PAGE_SIZES[k].width===size.width&&PAGE_SIZES[k].height===size.height)||'A4';if(document.activeElement!==$('pageSize'))$('pageSize').value=sizeName;if(document.activeElement!==$('orientation'))$('orientation').value=page.orientation||'portrait';const marginName=Object.keys(PAGE_MARGINS).find(k=>PAGE_MARGINS[k].top===page.margins.top&&PAGE_MARGINS[k].right===page.margins.right&&PAGE_MARGINS[k].left===page.margins.left)||'normal';if(document.activeElement!==$('pageMargin'))$('pageMargin').value=marginName;}
function fitCanvasPage(){const canvas=$('paper')?.closest('.canvas');const paper=$('paper');if(!canvas||!paper)return;const pageWidth=Number.parseFloat(paper.style.width)||paper.getBoundingClientRect().width||794;const available=Math.max(240,canvas.clientWidth-32);const scale=Math.min(1,available/pageWidth);paper.style.zoom=String(Math.round(scale*1000)/1000);canvas.style.setProperty('--page-scale',String(scale));}const canvasResizeObserver=new ResizeObserver(()=>fitCanvasPage());canvasResizeObserver.observe(document.querySelector('.canvas'));function updatePageSetup(){const doc=JSON.parse(JSON.stringify(editor.state.document));const size=PAGE_SIZES[$('pageSize').value]||PAGE_SIZES.A4;const orientation=$('orientation').value;const margins=PAGE_MARGINS[$('pageMargin').value]||PAGE_MARGINS.normal;for(const section of doc.sections){section.page={...section.page,size:{...size},orientation,margins:{...margins}}}if(replaceModel(doc))$('status').textContent=`Page setup applied: ${$('pageSize').value}, ${orientation}, ${$('pageMargin').value} margins`;}
for(const id of ['pageSize','orientation','pageMargin'])$(id).addEventListener('change',updatePageSetup);function render(){const doc=editor.state.document;lastValid=doc;const jsonEl=$('json');const keepTop=jsonEl.scrollTop,keepLeft=jsonEl.scrollLeft;jsonEl.value=JSON.stringify(doc,null,2);jsonEl.scrollTop=keepTop;jsonEl.scrollLeft=keepLeft;const issues=coreSchema.validate(doc);$('issuecount').textContent=String(issues.length);$('issues').innerHTML=issues.length?`<strong class="bad">${issues.length} schema issue(s)</strong><ul>${issues.slice(0,8).map(i=>`<li>${esc(i.path)} — ${esc(i.message)}</li>`).join('')}</ul>`:'<strong class="good">● Valid against schema v1</strong><p>The current model passes the core schema validation.</p>';$('validstatus').textContent=issues.length?'● Schema issues detected':'● Valid against schema v1';$('validstatus').className=issues.length?'bad':'good';$('metastats').textContent=`${doc.sections.length} section(s) · ${countNodes(doc.sections)} nodes · model v${doc.schemaVersion}`;$('status').textContent=`${issues.length?'Needs attention':'valid'} · v${doc.schemaVersion} · ${doc.sections.length} section(s)`;const paper=$('paper');applyPagePreview(doc,paper);if(currentView==='json'){paper.innerHTML=`<pre>${esc(JSON.stringify(doc,null,2))}</pre>`}else if(currentView==='text'){paper.innerHTML=`<pre>${esc(flatText(doc.sections))}</pre>`}else if(currentView==='html'){paper.innerHTML=`<pre>${esc(doc.sections.map(s=>s.content.map(blockHtml).join('\n')).join('\n'))}</pre>`}else{paper.innerHTML=doc.sections.map((s,sectionIndex)=>{if(s.kind==='canvas')return canvasSheetHtml(s,sectionIndex,doc);return `<div class="letterhead" data-section-index="${sectionIndex}"><div class="drag-region-label">Header — seret blok untuk menyusun ulang atau seret gambar ke posisi</div><div class="image-position-tools" data-section-index="${sectionIndex}" data-region="header"><span>Posisi gambar:</span><div class="image-position-zone" data-image-align="left" title="Letakkan gambar di kiri">Kiri</div><div class="image-position-zone" data-image-align="center" title="Letakkan gambar di tengah">Tengah</div><div class="image-position-zone" data-image-align="right" title="Letakkan gambar di kanan">Kanan</div></div><div class="document-block-list header-block-list" data-section-index="${sectionIndex}" data-region="header">${(s.header||[]).map((block,blockIndex)=>`<div class="doc-block${block.type==='image'?' image-block':''}" data-block-id="${esc(block.id||'')}" data-block-index="${blockIndex}" draggable="${block.id&&block.type!=='image'?'true':'false'}">${blockHtml(block)}</div>`).join('')}</div></div><div class="document-block-list" data-section-index="${sectionIndex}" data-region="content">${s.content.map((block,blockIndex)=>`<div class="doc-block${block.type==='image'?' image-block':''}" data-block-id="${esc(block.id||'')}" data-block-index="${blockIndex}" draggable="${block.id&&block.type!=='image'?'true':'false'}">${blockHtml(block)}</div>`).join('')}</div><div class="letterfoot" data-section-index="${sectionIndex}"><div class="drag-region-label">Footer — seret blok untuk menyusun ulang</div><div class="document-block-list footer-block-list" data-section-index="${sectionIndex}" data-region="footer">${(s.footer||[]).map((block,blockIndex)=>`<div class="doc-block${block.type==='image'?' image-block':''}" data-block-id="${esc(block.id||'')}" data-block-index="${blockIndex}" draggable="${block.id&&block.type!=='image'?'true':'false'}">${blockHtml(block)}</div>`).join('')}</div></div>`}).join('')}renderHeaderFooterVariants(doc);renderFields(doc);renderInspector(doc);applyImageSelection();applyBoxSelection();requestAnimationFrame(()=>{fitCanvasPage();schedulePagesRefresh()});}
function renderHeaderFooterVariants(doc){if(currentView!=='preview')return;const variants=[{key:'firstPageHeader',label:'Header halaman pertama',host:'.letterhead'},{key:'evenPageHeader',label:'Header halaman genap',host:'.letterhead'},{key:'firstPageFooter',label:'Footer halaman pertama',host:'.letterfoot'},{key:'evenPageFooter',label:'Footer halaman genap',host:'.letterfoot'}];for(let sectionIndex=0;sectionIndex<doc.sections.length;sectionIndex++){const section=doc.sections[sectionIndex];if(section.kind==='canvas')continue;for(const variant of variants){const host=$('paper').querySelectorAll('.letterhead, .letterfoot');const base=Array.from(host).find(el=>Number(el.closest('[data-section-index]')?.dataset.sectionIndex??sectionIndex)===sectionIndex&&el.matches(variant.host));if(!base)continue;const panel=document.createElement('div');panel.className='variant-region';panel.dataset.sectionIndex=String(sectionIndex);panel.dataset.region=variant.key;panel.innerHTML=`<div class="drag-region-label">${variant.label} · editable</div><div class="document-block-list variant-block-list" data-section-index="${sectionIndex}" data-region="${variant.key}">${(section[variant.key]||[]).map((block,blockIndex)=>`<div class="doc-block variant-doc-block" data-block-index="${blockIndex}">${blockHtml(block)}<button type="button" class="variant-remove" data-remove-variant="${variant.key}" data-section-index="${sectionIndex}" data-block-index="${blockIndex}">Hapus blok</button></div>`).join('')}</div><button type="button" class="variant-add" data-add-variant="${variant.key}" data-section-index="${sectionIndex}">+ Tambah blok</button>`;base.append(panel);}}}
$('paper').addEventListener('click',event=>{const remove=event.target.closest('[data-remove-variant]');const add=event.target.closest('[data-add-variant]');if(!remove&&!add)return;const button=remove||add,sectionIndex=Number(button.dataset.sectionIndex),slot=remove?remove.dataset.removeVariant:add.dataset.addVariant;const doc=JSON.parse(JSON.stringify(editor.state.document));const section=doc.sections[sectionIndex];if(!section||!['firstPageHeader','firstPageFooter','evenPageHeader','evenPageFooter'].includes(slot))return;if(remove){const index=Number(remove.dataset.blockIndex);if(!Array.isArray(section[slot])||!section[slot][index])return;section[slot].splice(index,1);if(!section[slot].length)section[slot]=[];if(replaceModel(doc))$('status').textContent=`Blok dihapus dari ${slot}`;return;}section[slot]=section[slot]||[];section[slot].push(p(''));if(replaceModel(doc))$('status').textContent=`Blok ditambahkan ke ${slot}`;});
function countNodes(nodes){let count=0;for(const node of nodes||[]){count++;if(node.content)count+=countNodes(node.content.filter(x=>x.id));}return count;}
function flatText(sections){const out=[];const walk=nodes=>{for(const x of nodes||[]){if(x.type==='text')out.push(x.text);else if(x.id){if(x.type==='table')out.push('\n[TABLE]\n');walk(x.content);out.push('\n')}else if(x.type==='placeholder')out.push(`{{${x.attrs?.key||'unknown'}}}`)}};for(const s of sections)walk(s.content);return out.join('').replace(/\n{3,}/g,'\n\n');}
function collectFields(nodes,set=new Set()){for(const x of nodes||[]){if(x.type==='placeholder'&&x.attrs?.key)set.add(x.attrs.key);if(x.type==='text'&&typeof x.text==='string'&&x.text.includes('{{')){for(const match of x.text.matchAll(/\{\{\s*([A-Za-z][A-Za-z0-9_-]*(?:\.[A-Za-z0-9_-]+)*)\s*\}\}/g))set.add(match[1]);}if(x.id&&x.content)collectFields(x.content,set);}return set;}
// Convert {{field.key}} text into native placeholder atoms when a document is opened.
// Traverse body, tables, headers, footers, and page variants without changing surrounding text/marks.
function normalizeDocumentPlaceholders(doc){let converted=0;const inlinePattern=/\{\{\s*([A-Za-z][A-Za-z0-9_-]*(?:\.[A-Za-z0-9_-]+)*)\s*\}\}/g;const walk=nodes=>{if(!Array.isArray(nodes))return;for(let i=0;i<nodes.length;){const node=nodes[i];if(node?.type==='text'&&typeof node.text==='string'){let end=i;while(end<nodes.length&&nodes[end]?.type==='text'&&typeof nodes[end].text==='string')end++;const group=nodes.slice(i,end);const full=group.map(x=>x.text).join('');const matches=[...full.matchAll(inlinePattern)];if(matches.length){const segments=[];let offset=0;for(const item of group){segments.push({start:offset,end:offset+item.text.length,node:item});offset+=item.text.length;}const replacement=[];let cursor=0;const addTextRange=(from,to)=>{for(const seg of segments){const a=Math.max(from,seg.start),b=Math.min(to,seg.end);if(a<b)replacement.push({...seg.node,text:full.slice(a,b)});}};for(const match of matches){const start=match.index,endMatch=start+match[0].length;if(start>cursor)addTextRange(cursor,start);replacement.push({type:'placeholder',attrs:{key:match[1]}});converted++;cursor=endMatch;}if(cursor<full.length)addTextRange(cursor,full.length);nodes.splice(i,group.length,...replacement);i+=replacement.length;continue;}i=end;continue;}if(node?.id&&Array.isArray(node.content))walk(node.content);i++;}};for(const section of doc.sections||[]){for(const region of ['header','content','footer','firstPageHeader','firstPageFooter','evenPageHeader','evenPageFooter'])walk(section[region]);}return converted;}
function visitNodes(nodes,callback){for(const node of nodes||[]){callback(node);if(node.id&&node.content)visitNodes(node.content,callback)}}
function replaceFieldKey(doc,oldKey,newKey){visitNodes(doc.sections, node=>{if(node.type==='placeholder'&&node.attrs?.key===oldKey)node.attrs.key=newKey;if(node.type==='text'&&typeof node.text==='string')node.text=node.text.replaceAll(`{{${oldKey}}}`,`{{${newKey}}}`)});}
function removeFieldKey(doc,key){const clean=nodes=>(nodes||[]).filter(node=>{if(node.type==='placeholder'&&node.attrs?.key===key)return false;if(node.type==='text'&&typeof node.text==='string')node.text=node.text.replaceAll(`{{${key}}}`,'');if(node.id&&node.content)node.content=clean(node.content);return true});for(const section of doc.sections){section.header=clean(section.header);section.content=clean(section.content);section.footer=clean(section.footer);section.firstPageHeader=clean(section.firstPageHeader);section.firstPageFooter=clean(section.firstPageFooter);section.evenPageHeader=clean(section.evenPageHeader);section.evenPageFooter=clean(section.evenPageFooter)}}
function fieldAction(label,action){const button=document.createElement('button');button.type='button';button.className='field-action';button.textContent=label;button.setAttribute('aria-label',label);button.onclick=action;return button;}
function renderFields(doc){const keys=[...collectFields(doc.sections.flatMap(s=>[...(s.header||[]),...s.content,...(s.footer||[]),...(s.firstPageHeader||[]),...(s.firstPageFooter||[]),...(s.evenPageHeader||[]),...(s.evenPageFooter||[])]))];$('fields').innerHTML='';let last='';for(const key of keys){const group=key.split('.')[0]||'CUSTOM';if(group!==last){const h=document.createElement('div');h.className='group';h.textContent=group.toUpperCase();$('fields').append(h);last=group}const row=document.createElement('div');row.className='fieldrow';const select=document.createElement('button');select.type='button';select.className='field-select';select.innerHTML=`<span class="fieldbody"><b>${esc(pathLabels[key]||key)}</b><code>{{${esc(key)}}}</code></span>`;select.onclick=()=>{const box=$('json');box.focus();const pos=box.value.indexOf(key);if(pos>=0)box.setSelectionRange(pos,pos+key.length);$('status').textContent=`Field selected: ${key}`};row.append(fieldGrip(),select,fieldAction('Edit',()=>editField(key)),fieldAction('Delete',()=>deleteField(key)));makeFieldDraggable(row,key);$('fields').append(row)}}
function validFieldKey(key){return /^[A-Za-z][A-Za-z0-9_-]*(?:\.[A-Za-z0-9_-]+)*$/.test(key)&&key.length<=120;}
function editField(oldKey){const next=prompt('Field key baru:',oldKey);if(next===null)return;const newKey=next.trim();if(!validFieldKey(newKey)){$('status').textContent='Invalid field key. Gunakan huruf di awal dan segmen dipisahkan titik.';return}if(newKey!==oldKey&&collectFields(editor.state.document.sections).has(newKey)){$('status').textContent=`Field ${newKey} sudah ada`;return}const oldLabel=pathLabels[oldKey]||oldKey;const label=prompt('Label field:',oldLabel);if(label===null)return;const doc=JSON.parse(JSON.stringify(editor.state.document));replaceFieldKey(doc,oldKey,newKey);if(replaceModel(doc)){delete pathLabels[oldKey];pathLabels[newKey]=label.trim()||newKey;if(fieldTypes.has(oldKey)){fieldTypes.set(newKey,fieldTypes.get(oldKey));fieldTypes.delete(oldKey)}renderFields(editor.state.document);$('status').textContent=`Field updated: ${oldKey} → ${newKey}`;}}
function deleteField(key){if(!confirm(`Hapus semua placeholder {{${key}}} dari dokumen?`))return;const doc=JSON.parse(JSON.stringify(editor.state.document));removeFieldKey(doc,key);if(replaceModel(doc)){delete pathLabels[key];fieldTypes.delete(key);$('status').textContent=`Field deleted: ${key}`;}}
function replaceModel(value){const parsed=parseDocument(value);if(!parsed.ok){$('issues').innerHTML=`<strong class="bad">Invalid document model</strong><ul>${parsed.issues.slice(0,10).map(i=>`<li>${esc(i.path)} — ${esc(i.message)}</li>`).join('')}</ul>`;$('issuecount').textContent=String(parsed.issues.length);return false}const result=editor.replaceDocument(parsed.document);if(!result.ok){$('issues').innerHTML=`<strong class="bad">${esc(result.error?.message||'Unable to replace document')}</strong>`;return false}render();return true;}
$('json').addEventListener('change',()=>{try{const value=JSON.parse($('json').value);const filled=ensureSectionContent(value);if(!replaceModel(value))$('status').textContent='JSON ditolak: schema validation gagal';else if(filled)$('status').textContent='Konten dikosongkan: paragraf kosong dipertahankan agar section tetap valid; teks lama dihapus dari preview.'}catch(e){$('status').textContent=`JSON parse error: ${e.message}`}});
$('format').onclick=()=>{try{$('json').value=JSON.stringify(JSON.parse($('json').value),null,2);$('status').textContent='JSON formatted'}catch(e){$('status').textContent=`JSON parse error: ${e.message}`}};
$('copy').onclick=async()=>{await navigator.clipboard.writeText(JSON.stringify(editor.state.document,null,2));$('status').textContent='Document JSON copied'};
