async function importDocumentFile(file){if(!file)return;const ext=file.name.split('.').pop()?.toLowerCase();$('status').textContent=`Reading ${file.name}…`;try{if(file.size>25*1024*1024)throw new Error('File exceeds 25 MiB import limit');if(ext==='json'){const value=JSON.parse(await file.text());const detected=normalizeDocumentPlaceholders(value);if(replaceModel(value))$('status').textContent=`Loaded ${file.name} into core model · ${collectFields(value.sections).size} placeholder(s) detected${detected?` · ${detected} converted to field token(s)`:''}`;return}if(ext!=='docx'&&ext!=='dotx')throw new Error('Unsupported file. Choose .docx, .dotx, or .json');const bytes=new Uint8Array(await file.arrayBuffer());if(bytes.length<4||bytes[0]!==0x50||bytes[1]!==0x4b)throw new Error('File is not a valid OOXML ZIP package');const {importDocx}=await import('@convetlib/docx');const doc=await importDocx(bytes,{title:file.name.replace(/\.(docx|dotx)$/i,'')});const detected=normalizeDocumentPlaceholders(doc);const detectedKeys=collectFields((doc.sections||[]).flatMap(s=>[...(s.header||[]),...(s.content||[]),...(s.footer||[]),...(s.firstPageHeader||[]),...(s.firstPageFooter||[]),...(s.evenPageHeader||[]),...(s.evenPageFooter||[])]));if(!replaceModel(doc))throw new Error('Imported document failed core schema validation');const sections=doc.sections||[];const nodes=allNodes(sections.flatMap(s=>[...(s.header||[]),...(s.content||[]),...(s.footer||[])]));const count=type=>nodes.filter(node=>node.type===type).length;const textLength=nodes.reduce((n,node)=>n+(node.type==='text'&&typeof node.text==='string'?node.text.length:0),0);$('status').textContent=`Imported ${file.name} · ${sections.length} section(s) · ${count('paragraph')} paragraph(s) · ${count('table')} table(s) · ${count('image')} image(s) · ${detectedKeys.size} placeholder(s) detected${detected?` · ${detected} converted to field token(s)`:''} · ${textLength} text characters`;const title=$('docTitle');if(title)title.value=doc.meta?.title||file.name.replace(/\.(docx|dotx)$/i,'');}catch(err){$('status').textContent=`Import failed: ${err instanceof Error?err.message:String(err)}`;throw err}}
$('file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{await importDocumentFile(file)}catch{}finally{e.target.value=''}};
