function parsePlaceholderCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted&&c==='"'&&text[i+1]==='"'){cell+='"';i++;continue}if(c==='"'){quoted=!quoted;continue}if(!quoted&&(c===','||c==='\\t')){row.push(cell.trim());cell='';continue}if(!quoted&&(c==='\\n'||c==='\\r')){if(c==='\\r'&&text[i+1]==='\\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell='';continue}cell+=c}row.push(cell.trim());if(row.some(Boolean))rows.push(row);if(!rows.length)return [];const headers=rows[0].map(v=>v.toLowerCase());const hasHeader=headers.some(v=>['key','field','field_key','placeholder','label','type','data_type'].includes(v));const data=hasHeader?rows.slice(1):rows;return data.map(r=>{const get=(names,index)=>{const ix=headers.findIndex(h=>names.includes(h));return (ix>=0?r[ix]:r[index])||''};return {key:get(['key','field','field_key','placeholder'],0),label:get(['label','name','title'],1),type:get(['type','data_type'],2)||'text'}})}
