$('placeholderFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('File maksimal 5 MiB');const ext=file.name.split('.').pop().toLowerCase();let items;if(ext==='json'){const raw=JSON.parse(await file.text());items=Array.isArray(raw)?raw:(raw.placeholders||raw.fields||raw.items);if(!Array.isArray(items))throw new Error('JSON harus berupa array atau objek dengan properti placeholders, fields, atau items')}else if(ext==='csv')items=parsePlaceholderCsv(await file.text());else throw new Error('Format hanya JSON atau CSV');const normalized=items.map((x,i)=>({key:String(x.key??x.field_key??x.placeholder??x.name??'').trim().replace(/^{{|}}$/g,''),label:String(x.label??x.title??x.name??x.key??'').trim(),type:String(x.type??x.data_type??'text').trim()||'text',row:i+1}));const invalid=normalized.filter(x=>!validFieldKey(x.key));if(invalid.length)throw new Error('Key placeholder tidak valid pada baris/objek: '+invalid.map(x=>x.row).join(', '));const unique=new Map();for(const x of normalized)if(!unique.has(x.key))unique.set(x.key,x);const doc=JSON.parse(JSON.stringify(editor.state.document));const existing=collectFields(doc.sections);const additions=[...unique.values()].filter(x=>!existing.has(x.key));if(!additions.length)throw new Error('Semua placeholder sudah ada di dokumen');const target=doc.sections.flatMap(s=>s.content||[]).find(x=>x.type==='paragraph');if(!target)throw new Error('Tidak ada paragraf konten untuk menyisipkan placeholder');target.content=[...(target.content||[])];for(const item of additions){target.content.push({type:'text',text:' '},{type:'placeholder',attrs:{key:item.key}});pathLabels[item.key]=item.label||item.key;fieldTypes.set(item.key,item.type)}if(!replaceModel(doc))throw new Error('Dokumen ditolak validasi schema');renderFields(editor.state.document);$('status').textContent='Import placeholder berhasil: '+additions.length+' ditambahkan, '+(normalized.length-additions.length)+' duplikat/yang sudah ada dilewati.'}catch(err){$('status').textContent='Import placeholder gagal: '+(err instanceof Error?err.message:String(err))}finally{e.target.value=''}};
$('addfield').onclick=()=>{const key=$('custompath').value.trim();const label=$('customlabel').value.trim()||key;const type=$('fieldtype').value;if(!validFieldKey(key)){$('status').textContent='Field key tidak valid. Contoh: pegawai.nama';return}if(collectFields(editor.state.document.sections).has(key)){$('status').textContent=`Field ${key} sudah ada`;return}const doc=JSON.parse(JSON.stringify(editor.state.document));const target=doc.sections.flatMap(s=>s.content||[]).find(x=>x.type==='paragraph');if(!target){$('status').textContent='Tidak ada paragraf untuk menambahkan placeholder';return}target.content=[...(target.content||[]),{type:'text',text:' '},{type:'placeholder',attrs:{key}}];if(replaceModel(doc)){pathLabels[key]=label;fieldTypes.set(key,type);$('custompath').value='';$('customlabel').value='';$('status').textContent=`Field added: ${label} (${type})`;renderFields(editor.state.document)}};function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
