﻿// ---- Save project -------------------------------------------------------------------------------------------------
// Local (localhost / 127.0.0.1 / file:) -> written to a file on this computer through the File System Access API; Ctrl+S
// re-saves to the same file, Ctrl+Shift+S asks for a new one. Website -> a guidance dialog explains where the file goes,
// then the browser saves it (picker when supported, otherwise a normal download). The file is the plain document JSON,
// so "Open .json" reads it back unchanged. Add ?storage=local or ?storage=web to the URL to force a mode.
function storageMode(){const forced=new URLSearchParams(location.search).get('storage');if(forced==='local'||forced==='web')return forced;const host=location.hostname;return(host===''||host==='localhost'||host==='127.0.0.1'||host==='[::1]'||host==='::1'||host.endsWith('.localhost'))?'local':'web'}
let projectHandle=null;
const guideStore={get:key=>{try{return localStorage.getItem(key)}catch{return null}},set:(key,value)=>{try{localStorage.setItem(key,value)}catch{}}};
function projectFileName(){const title=String(editor.state.document.meta?.title||'').normalize('NFKD').replace(/[^\w\s-]/g,'').trim().replace(/\s+/g,'-').toLowerCase().slice(0,60);return `${title||'proyek-convetlib'}.convetlib.json`}
async function writeProject(handle,text){const writable=await handle.createWritable();try{await writable.write(text)}finally{await writable.close()}}
async function saveProjectFile({saveAs=false}={}){const text=JSON.stringify(editor.state.document,null,2);const name=projectFileName();
if(typeof window.showSaveFilePicker==='function'){try{if(!projectHandle||saveAs)projectHandle=await window.showSaveFilePicker({suggestedName:name,types:[{description:'Proyek Convetlib (JSON)',accept:{'application/json':['.json']}}]});await writeProject(projectHandle,text);$('status').textContent=`Proyek disimpan ke berkas: ${projectHandle.name}${storageMode()==='local'?' (di komputer ini)':''}`;return true}catch(error){if(error?.name==='AbortError'){$('status').textContent='Penyimpanan dibatalkan.';return false}projectHandle=null}}
download(new Blob([text],{type:'application/json'}),name);$('status').textContent=`Proyek diunduh sebagai ${name}. Cek folder Unduhan (Downloads) peramban Anda.`;return true}
function webSaveGuidance(){return new Promise(resolve=>{if(guideStore.get('convetlibSaveGuide')==='skip'){resolve(true);return}
$('saveGuideDialog')?.remove();const dialog=document.createElement('dialog');dialog.id='saveGuideDialog';dialog.className='shortcut-dialog save-guide-dialog';
dialog.innerHTML=`<form method="dialog"><h2>Simpan proyek dari website</h2><p>Proyek <b>tidak disimpan di server</b>. Berkas <b>${esc(projectFileName())}</b> disimpan di perangkat Anda.</p><ol><li>Klik <b>Simpan sekarang</b>. Di Chrome/Edge akan muncul jendela <b>Simpan sebagai</b>: pilih folder tujuan.</li><li>Jika jendela itu tidak muncul, berkas masuk ke folder <b>Unduhan (Downloads)</b>. Agar bisa memilih folder: Chrome/Edge &rarr; Pengaturan &rarr; Unduhan &rarr; aktifkan <i>Tanyakan lokasi penyimpanan setiap kali</i>; Firefox &rarr; Pengaturan &rarr; Umum &rarr; Berkas dan Aplikasi &rarr; <i>Selalu tanya di mana berkas disimpan</i>.</li><li>Simpan salinan cadangan (Google Drive, OneDrive, atau flash disk). Website tidak menyimpan otomatis.</li><li>Untuk membuka lagi: tombol <b>Open .docx/.dotx/.json</b>, lalu pilih berkas ini.</li></ol><label class="guide-skip"><input type="checkbox" id="saveGuideSkip"> Jangan tampilkan arahan ini lagi</label><div class="shortcut-actions"><button value="cancel" class="secondary">Batal</button><button value="ok">Simpan sekarang</button></div></form>`;
$('app').append(dialog);dialog.addEventListener('close',()=>{const confirmed=dialog.returnValue==='ok';if(confirmed&&dialog.querySelector('#saveGuideSkip')?.checked)guideStore.set('convetlibSaveGuide','skip');dialog.remove();resolve(confirmed)});dialog.showModal()})}
async function saveProject(options={}){if(storageMode()==='web'&&(!projectHandle||options.saveAs)&&!(await webSaveGuidance())){$('status').textContent='Penyimpanan dibatalkan.';return false}return saveProjectFile(options)}
$('saveProject').title=storageMode()==='local'?'Simpan proyek ke berkas di komputer ini (Ctrl+S, Ctrl+Shift+S = simpan sebagai)':'Simpan proyek: arahan penyimpanan akan ditampilkan (Ctrl+S)';
$('saveProject').onclick=event=>{saveProject({saveAs:event.shiftKey})};
function showShortcuts(){let dialog=$('shortcutDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='shortcutDialog';dialog.className='shortcut-dialog';dialog.innerHTML='<form method="dialog"><h2>Pintasan keyboard</h2><p><kbd>Ctrl</kbd> + <kbd>B</kbd> \u2014 Tebal</p><p><kbd>Ctrl</kbd> + <kbd>I</kbd> \u2014 Miring</p><p><kbd>Ctrl</kbd> + <kbd>U</kbd> \u2014 Garis bawah</p><p><kbd>Ctrl</kbd> + <kbd>S</kbd> \u2014 Simpan proyek (lokal: ke berkas di komputer; website: arahan + unduh)</p><p><kbd>Ctrl</kbd> + <kbd>Shift</kbd> + <kbd>S</kbd> \u2014 Simpan sebagai berkas baru</p><p><kbd>Delete</kbd> / <kbd>Backspace</kbd> \u2014 Hapus elemen canvas terpilih (klik gagang biru atau gambar)</p><p><kbd>Shift</kbd> + <kbd>?</kbd> \u2014 Buka pintasan keyboard</p><p><kbd>Esc</kbd> \u2014 Tutup dialog / batalkan drag</p><div class="shortcut-actions"><button value="close">Tutup</button></div></form>';$('app').append(dialog)}if(!dialog.open)dialog.showModal()}
$('shortcuts').onclick=showShortcuts;
document.addEventListener('keydown',event=>{const target=event.target instanceof Element?event.target:null;const formControl=!!target?.closest('input,textarea,select,[role="textbox"]')&&!target?.closest('#paper');if((event.shiftKey&&event.key==='?')|| (event.key==='/'&&event.shiftKey)){event.preventDefault();showShortcuts();return}if(event.key==='Escape'&&$('shortcutDialog')?.open){$('shortcutDialog').close();return}if((event.ctrlKey||event.metaKey)&&!event.altKey){const key=event.key.toLowerCase();if(key==='s'){event.preventDefault();saveProject({saveAs:event.shiftKey});return}if(!formControl&&key==='b'){event.preventDefault();runEditorCommand('text.toggleBold');return}if(!formControl&&key==='i'){event.preventDefault();runEditorCommand('text.toggleItalic');return}if(!formControl&&key==='u'){event.preventDefault();runEditorCommand('text.toggleUnderline');return}}});
function allNodes(nodes,out=[]){for(const node of nodes||[]){out.push(node);if(node.id&&node.content)allNodes(node.content,out)}return out}
function metric(label,value){return `<div class="metric"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`}
function renderInspector(doc){
  const sections=doc.sections||[];const nodes=allNodes(sections.flatMap(s=>[...(s.header||[]),...(s.content||[]),...(s.footer||[])]));
  const placeholders=new Set();for(const node of nodes){if(node.type==='placeholder'&&node.attrs?.key)placeholders.add(node.attrs.key);if(node.type==='text'&&node.text){for(const part of node.text.split('{{').slice(1)){const key=part.split('}}')[0]?.trim();if(key&&!key.includes('{'))placeholders.add(key)}}}
  const title=$('docTitle');if(title&&document.activeElement!==title)title.value=doc.meta?.title||'';
  $('dataDetails').innerHTML=metric('Document ID',doc.id)+metric('Schema version',doc.schemaVersion)+metric('Sections',sections.length)+metric('Placeholders',placeholders.size)+metric('Comments',Object.keys(doc.comments||{}).length)+metric('Revisions',Object.keys(doc.revisions||{}).length);
  $('schemaDetails').innerHTML=`<div class="group">BLOCK / INLINE NODES (${coreSchema.nodeNames().length})</div><div class="schema-list">${coreSchema.nodeNames().map(name=>`<span class="schema-token">${esc(name)}</span>`).join('')}</div><div class="group">MARKS (${coreSchema.markNames().length})</div><div class="schema-list">${coreSchema.markNames().map(name=>`<span class="schema-token">${esc(name)}</span>`).join('')}</div>`;
  const count=type=>nodes.filter(node=>node.type===type).length;const bytes=new TextEncoder().encode(JSON.stringify(doc)).length;
  $('statsDetails').innerHTML=metric('Total nodes',nodes.length)+metric('Paragraphs',count('paragraph'))+metric('Headings',count('heading'))+metric('Tables',count('table'))+metric('Rows',count('tableRow'))+metric('Cells',count('tableCell'))+metric('Images',count('image'))+metric('Placeholders',placeholders.size)+metric('JSON size',`${bytes.toLocaleString()} bytes`)+metric('Schema issues',coreSchema.validate(doc).length);
  $('pluginDetails').innerHTML=`<div class="info"><b>Core model & schema</b><p>Loaded · ${coreSchema.nodeNames().length} node types and ${coreSchema.markNames().length} mark types.</p></div><div class="info" style="margin-top:8px"><b>Browser editor adapter</b><p>Loaded · selection binding and formatting commands registered.</p></div><div class="info" style="margin-top:8px"><b>DOCX adapter</b><p>Loaded · import and export functions available. Complex document fidelity still requires manual verification.</p></div><div class="info" style="margin-top:8px"><b>PDF adapter</b><p>Loaded · PDF export function available. Layout fidelity still requires manual verification.</p></div><p class="panel-copy">This playground currently has no runtime plugin installer or plugin registry UI. This panel reports the adapters wired into this example.</p>`;
}
document.querySelectorAll('[data-panel]').forEach(button=>button.addEventListener('click',()=>{const name=button.dataset.panel;document.querySelectorAll('[data-panel]').forEach(tab=>tab.classList.toggle('selected',tab===button));document.querySelectorAll('[data-panel-content]').forEach(panel=>panel.hidden=panel.dataset.panelContent!==name)}));
$('applyTitle').onclick=()=>{const doc=JSON.parse(JSON.stringify(editor.state.document));doc.meta={...(doc.meta||{}),title:$('docTitle').value.trim()};if(!doc.meta.title){$('status').textContent='Document title cannot be empty';return}if(replaceModel(doc))$('status').textContent='Document title updated'};
initPagesCanvas({PAGE_SIZES,esc,blockHtml,ids,getView:()=>currentView,getEditor:()=>editor,replaceModel,allNodes,render,clearImageSelection:()=>{selectedImage=null;applyImageSelection()},hasSelectedImage:()=>!!selectedImage,deleteSelectedImage});
render();
